package trayui

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func px(p []uint32, size, x, y int) [4]uint8 {
	v := p[y*size+x]
	return [4]uint8{uint8(v >> 24), uint8(v >> 16), uint8(v >> 8), uint8(v)}
}

// TestCHK_TRAY_89_AppIconGreenArrows — the main icon keeps the blue
// background and has green arrows (no white left); the exe / installer
// .ico (cmd/exchtray/exchtray.ico, 16/32/48) and the window icon
// (internal/wintray/icons/app.ico) are the generated bytes.
func TestCHK_TRAY_89_AppIconGreenArrows(t *testing.T) {
	for _, s := range []int{16, 32, 48} {
		p := AppIconPixels(ArrowGreen, s)
		bg := px(p, s, s/2, s-2)             // bottom edge: background
		top := px(p, s, s*20/48, s*17/48)    // shaft of →
		bottom := px(p, s, s*30/48, s*31/48) // shaft of ←
		if bg != [4]uint8{255, AppBlue[0], AppBlue[1], AppBlue[2]} {
			t.Errorf("%d: background %v", s, bg)
		}
		for _, a := range [][4]uint8{top, bottom} {
			if a != [4]uint8{255, ArrowGreen[0], ArrowGreen[1], ArrowGreen[2]} {
				t.Errorf("%d: arrow %v", s, a)
			}
		}
		green, white := 0, 0
		for i := range p {
			c := px(p, s, i%s, i/s)
			if c[0] == 255 && c[1] == ArrowGreen[0] && c[2] == ArrowGreen[1] && c[3] == ArrowGreen[2] {
				green++
			}
			if c[0] == 255 && c[1] == 255 && c[2] == 255 && c[3] == 255 {
				white++
			}
		}
		if green < s*s/10 || white != 0 {
			t.Errorf("%d: green %d white %d", s, green, white)
		}
	}
	ico := ExeICO()
	if ico[4] != 3 || !bytes.Equal(ico, ExeICO()) {
		t.Fatal("exe icon: 3 images, deterministic")
	}
	for _, s := range ExeIconSizes {
		d, err := DecodeICO(ico, s)
		if err != nil || d[(s/2)*s+s/2>>0] == 0 {
			t.Fatalf("%d: %v", s, err)
		}
	}
	committed, err := os.ReadFile(filepath.Join("..", "..", "cmd", "exchtray", "exchtray.ico"))
	if err != nil || !bytes.Equal(committed, ico) {
		t.Errorf("cmd/exchtray/exchtray.ico is not trayui.ExeICO (run go run ./tools/mkres): %v", err)
	}
	app, err := os.ReadFile(filepath.Join("..", "wintray", "icons", IcoApp+".ico"))
	want, _ := IconICO(IcoApp)
	if err != nil || !bytes.Equal(app, want) {
		t.Errorf("internal/wintray/icons/app.ico stale: %v", err)
	}
	if a, _ := iconImage(IcoApp, 32); !equalPx(a, AppIconPixels(ArrowGreen, 32)) {
		t.Error("IcoApp must be the green-arrow app icon")
	}
}

func equalPx(a, b []uint32) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
